css:
@import url("https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,500;0,700;1,500&family=Nunito+Sans:opsz,wght@6..12,400;6..12,700&display=swap");
:root{--br:#6B3A2A;--cr:#C9824E;--pk:#F6D8CF;--pk-l:#FDF1EC;--sg:#8FA67E;--tx:#3A2A24;--mu:#7C6A62;--ln:#EFDDD3;--s:"Lora",Georgia,serif;--b:"Nunito Sans",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:18px;line-height:1.6;color:var(--tx);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--s);font-weight:700;margin:0;line-height:1.08;color:var(--br)}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--pk);padding:8px;z-index:99}:focus-visible{outline:3px solid var(--cr);outline-offset:3px;border-radius:8px}
.top{background:var(--br);color:var(--pk);text-align:center;font-size:15px;padding:8px}
.nav{display:flex;justify-content:space-between;align-items:center;height:80px}.logo{font-family:var(--s);font-style:italic;font-size:30px;text-decoration:none;color:var(--br)}
.menu{display:flex;gap:24px;list-style:none;margin:0;padding:0;font-weight:700}.menu a{text-decoration:none}.menu a:hover{color:var(--cr)}
.btn{display:inline-flex;align-items:center;justify-content:center;padding:13px 24px;border-radius:999px;font-weight:700;text-decoration:none;border:2px solid var(--br);font-family:var(--b);font-size:16px;cursor:pointer}
.btn-b{background:var(--br);color:#fff}.btn-l{background:transparent;color:var(--br)}.burger{display:none;background:none;border:2px solid var(--br);border-radius:10px;padding:6px 10px;cursor:pointer}
.hero{background:var(--pk-l)}.hg{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:40px;padding:50px 0}
.hero h1{font-size:clamp(46px,6.4vw,88px)}.hero h1 em{color:var(--cr)}.hero p{font-size:20px;color:var(--mu);max-width:40ch;margin:18px 0 26px}
.hi{display:grid;grid-template-columns:1fr 1fr;gap:14px}.hi img{border-radius:24px;object-fit:cover;width:100%}.hi img:first-child{grid-row:span 2;height:100%}.hi img:not(:first-child){aspect-ratio:1/1}
section{padding:80px 0}.sh{text-align:center;margin-bottom:32px}.sh h2{font-size:clamp(38px,4.8vw,60px)}.sh p{color:var(--mu);margin:10px 0 0}
.today{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.bk{border:2px solid var(--ln);border-radius:22px;padding:18px;text-align:center;position:relative}
.bk .e{font-size:54px}.bk h3{font-size:21px;margin:6px 0 4px}.bk small{color:var(--mu)}.bk .rw{display:flex;justify-content:space-between;align-items:center;margin-top:12px}
.bk .rw b{font-size:18px}.bk button{background:var(--br);color:#fff;border:0;border-radius:999px;padding:8px 14px;font:inherit;font-weight:700;font-size:14px;cursor:pointer}
.bk.out{opacity:.55}.bk.out button{background:var(--mu);cursor:not-allowed}.bk .so{position:absolute;top:12px;right:12px;background:var(--br);color:#fff;font-size:12px;font-weight:700;border-radius:6px;padding:2px 8px}
.left{font-size:14px;color:var(--cr);font-weight:700;display:block;margin-top:4px}
.cake{background:var(--pk-l)}.cg{display:grid;grid-template-columns:1fr 1fr;gap:34px;align-items:start}
.grp{margin-bottom:18px}.grp>b{display:block;margin-bottom:8px}.opts{display:flex;gap:8px;flex-wrap:wrap}.opts button{border:2px solid var(--ln);background:#fff;border-radius:14px;padding:10px 14px;font:inherit;font-weight:700;cursor:pointer;color:var(--tx)}
.opts button[aria-pressed=true]{border-color:var(--br);background:var(--br);color:#fff}.opts small{display:block;font-weight:400;font-size:13px}
.cg input{width:100%;border:2px solid var(--ln);border-radius:14px;padding:11px 14px;font:inherit;background:#fff}
.prev{background:#fff;border-radius:28px;padding:26px;text-align:center;position:sticky;top:20px}.prev svg{width:100%;max-width:300px;margin:0 auto}
.prev .am{font-family:var(--s);font-size:44px;color:var(--br);margin:8px 0}.prev p{margin:0;color:var(--mu)}
.story{display:grid;grid-template-columns:1fr 1fr;gap:50px;align-items:center}.story img{border-radius:24px;aspect-ratio:4/3;object-fit:cover;width:100%}.story h2{font-size:clamp(34px,4vw,50px);margin-bottom:12px}.story p{color:var(--mu)}
.faq{max-width:800px;margin:0 auto}.faq details{border-bottom:2px solid var(--ln);padding:16px 0}.faq summary{cursor:pointer;font-weight:700;font-size:19px;list-style:none;color:var(--br)}.faq summary::-webkit-details-marker{display:none}.faq p{color:var(--mu);margin:8px 0 0}
footer{background:var(--br);color:#E9CFC4;padding:40px 0;font-size:15px}.ft{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.ft b{color:#fff;display:block;margin-bottom:6px}.ft a{color:#fff}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,120px);background:var(--br);color:#fff;padding:12px 22px;border-radius:999px;transition:.3s;z-index:70;visibility:hidden;font-weight:700}.toast.show{transform:translate(-50%,0);visibility:visible}
@media(max-width:940px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:80px;left:0;right:0;background:#fff;padding:20px;gap:14px;z-index:30}.nav{position:relative}
.hg,.cg,.story,.ft{grid-template-columns:1fr}.today{grid-template-columns:1fr 1fr}.prev{position:static}}
@media(max-width:520px){.today{grid-template-columns:1fr}}

javascript:
const B=[["🍞","Country sourdough","800 g",4.8,6],["🥐","Butter croissant","each",2.4,14],["🥖","French baguette","each",2.2,0],["🥯","Cinnamon bun","each",3.1,3],["🧁","Vanilla cupcake","each",2.9,11],["🍪","Oat and raisin cookie","each",1.8,20],["🥧","Apple pie","serves 6",14,2],["🍰","Carrot cake slice","each",3.8,0]];
const $=id=>document.getElementById(id);let bc=0;function toast(t){const x=$('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function bakes(){$('bakes').innerHTML=B.map((b,i)=>`<article class="bk ${b[4]?'':'out'}">${b[4]?'':'<span class="so">Sold out</span>'}<div class="e" aria-hidden="true">${b[0]}</div><h3>${b[1]}</h3><small>${b[2]}</small>${b[4]&&b[4]<=3?`<span class="left">Only ${b[4]} left</span>`:''}<div class="rw"><b>£${b[3].toFixed(2)}</b><button type="button" data-i="${i}" ${b[4]?'':'disabled'}>${b[4]?'Add':'Gone'}</button></div></article>`).join('')}
$('bakes').onclick=e=>{const b=e.target.closest('[data-i]');if(!b||b.disabled)return;B[b.dataset.i][4]--;bc++;$('bc').textContent=bc;toast(B[b.dataset.i][1]+' added');bakes()};bakes();
const on=id=>$(id).querySelector('[aria-pressed=true]');['sz','fl','ic'].forEach(id=>$(id).onclick=e=>{const b=e.target.closest('button');if(!b)return;$(id).querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));cake()});
function tier(y,w,h,sp,ic){return `<rect x="${150-w/2}" y="${y}" width="${w}" height="${h}" rx="10" fill="${sp}"/><path d="M${150-w/2} ${y+10}q0-10 10-10h${w-20}q10 0 10 10v12${Array.from({length:6},(_,i)=>`q${-w/12} 14 ${-w/6} 0`).join('')}z" fill="${ic}"/>`}
function cake(){const s=on('sz'),f=on('fl'),c=on('ic');let g='';const t=+s.dataset.t;
if(t===2){g+=tier(150,210,78,f.dataset.c,c.dataset.c)+tier(80,140,70,f.dataset.c,c.dataset.c)}else{const w=s.dataset.v==='6 inch'?170:210;g+=tier(130,w,98,f.dataset.c,c.dataset.c)}
$('cakeG').innerHTML=g;const top=t===2?74:124;$('ct').setAttribute('y',top);$('ct').textContent=$('msg').value;
$('cn').textContent=s.dataset.v+' '+f.dataset.v.toLowerCase()+' cake';$('cd').textContent=c.dataset.v+($('msg').value?', with "'+$('msg').value+'"':'');$('cp').textContent=+s.dataset.p+ +f.dataset.p+ +c.dataset.p}
$('msg').oninput=cake;const d=new Date(Date.now()+3*864e5).toISOString().slice(0,10);$('dt').min=d;$('dt').value=d;cake();
$('cadd').onclick=()=>{bc++;$('bc').textContent=bc;toast($('cn').textContent+' added for '+$('dt').value)};
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
